questionvariables.text:
/* Exponential f(x) = b^x; base b in {2,3,4,5}, answer n1 in {-3,-2,-1,2,3}. n1 = 0 is excluded so the sign diagnostic -n1 never equals the answer. */
b: rand([2,3,4,5]);
n1: rand([-3,-2,-1,2,3]);
negn1: -n1;
f1: b^x;
output: b^n1;
correctanswer: n1;
/* Diagnostic: sign of the index wrong (for example 2 instead of -2) */
diag1: -n1;
